"""Fast circle packing for n=26 in the unit square."""
import numpy as np


def _radii(centers):
    """Compute max radii given centers via iterative relaxation. Fast."""
    centers = np.asarray(centers, dtype=float)
    n = centers.shape[0]
    d = np.zeros((n, n))
    for i in range(n):
        for j in range(i + 1, n):
            d[i, j] = d[j, i] = np.hypot(centers[i, 0] - centers[j, 0],
                                         centers[i, 1] - centers[j, 1])
    wall = np.minimum(np.minimum(centers[:, 0], centers[:, 1]),
                      np.minimum(1.0 - centers[:, 0], 1.0 - centers[:, 1]))
    r = wall.copy()
    for _ in range(300):
        changed = False
        for i in range(n):
            for j in range(i + 1, n):
                s = r[i] + r[j]
                if s > d[i, j] + 1e-12:
                    if s > 0:
                        scale = d[i, j] / s
                        r[i] *= scale
                        r[j] *= scale
                        changed = True
        if not changed:
            break
    return r


def construct_packing():
    n = 26
    # Base: 5x5 grid at spacing 0.2
    base = []
    for i in range(5):
        for j in range(5):
            base.append([0.1 + 0.2 * i, 0.1 + 0.2 * j])

    # Try placing the 26th circle at various candidate positions
    # and pick the one that maximizes total sum
    candidates = []
    # Gaps between grid points (midpoints)
    for i in range(4):
        for j in range(4):
            candidates.append([0.2 + 0.2 * i, 0.2 + 0.2 * j])
    # Corners
    for cx in [0.05, 0.95]:
        for cy in [0.05, 0.95]:
            candidates.append([cx, cy])
    # Edge midpoints
    for t in [0.05, 0.95]:
        candidates.append([0.5, t])
        candidates.append([t, 0.5])
    # Center
    candidates.append([0.5, 0.5])

    best_sum = -1
    best_centers = None
    for cand in candidates:
        centers = np.array(base + [cand])
        radii = _radii(centers)
        s = np.sum(radii)
        if s > best_sum:
            best_sum = s
            best_centers = centers.copy()

    radii = _radii(best_centers)
    return best_centers, radii, np.sum(radii)
