import numpy as np
from scipy.optimize import linprog


def _radii_lp(centers):
    """Exact max radii via LP."""
    centers = np.asarray(centers, dtype=float)
    n = centers.shape[0]
    c = -np.ones(n)
    A = []
    b = []
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(centers[i, 0] - centers[j, 0], centers[i, 1] - centers[j, 1])
            row = np.zeros(n)
            row[i] = 1.0
            row[j] = 1.0
            A.append(row)
            b.append(d)
    for i in range(n):
        x, y = centers[i]
        w = min(x, y, 1.0 - x, 1.0 - y)
        row = np.zeros(n)
        row[i] = 1.0
        A.append(row)
        b.append(w)
    A = np.array(A)
    b = np.array(b)
    bounds = [(0, None)] * n
    res = linprog(c, A_ub=A, b_ub=b, bounds=bounds, method='highs')
    if res.success:
        return np.maximum(res.x, 0)
    return np.minimum(np.minimum(centers[:, 0], centers[:, 1]),
                      np.minimum(1.0 - centers[:, 0], 1.0 - centers[:, 1]))


